contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint depositAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // read before-values
        uint beforeStored = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractEth = address(c).balance;

        // perform Deposit sending ETH
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // read after-values
        uint afterStored = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractEth = address(c).balance;

        // General property: Deposit always increases both the caller's stored balance and contract ETH by exactly depositAmt
        assert(afterStored == beforeStored + depositAmt && afterContractEth == beforeContractEth + depositAmt);
    }

    // allow receiving ETH if needed
    receive() external payable {}
}

