// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depositAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        uint256 beforeStored;
        try c.balances(address(this)) returns (uint256 __r) { beforeStored = __r; } catch { return; }
        uint beforeContractEth = address(c).balance;
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 afterStored;
        try c.balances(address(this)) returns (uint256 __r) { afterStored = __r; } catch { return; }
        uint afterContractEth = address(c).balance;
        assertTrue(afterStored == beforeStored + depositAmt && afterContractEth == beforeContractEth + depositAmt);
    }

    function testFuzz_run(uint256 depositAmt) public {
        _run(depositAmt);
    }

    receive() external payable {}
}
